"""Current-edition enquiry journeys; original event material stays in the archive."""
import re

def hero(kicker,title,copy,photo=None):
    media=(f'<figure><img src="/assets/edition-2026/{photo}.webp" alt="Participants at the first Élan Summit" width="1800" height="1013"><figcaption>FROM THE FIRST EDITION / SEPTEMBER 2026</figcaption></figure>' if photo else '<div class="visitor-monogram" aria-hidden="true">É<span>THE NEXT CHAPTER</span></div>')
    return f'<section class="visitor-hero container"><div><p class="section-label">{kicker}</p><h1>{title}</h1><p class="visitor-lead">{copy}</p></div>{media}</section>'

def ledger(kicker,title,rows):
    return '<section class="visitor-ledger container"><div><p class="section-label">'+kicker+'</p><h2>'+title+'</h2></div><div>'+''.join(f'<article><span>{i:02}</span><div><h3>{h}</h3><p>{p}</p></div></article>' for i,(h,p) in enumerate(rows,1))+'</div></section>'

def enquiry(main,title,copy):
    form=re.search(r'<form\b.*?</form>',main,re.S).group(0)
    form=form.replace('data-mode="email-draft"','data-mode="stored-enquiry"').replace('Prepare email draft','Send enquiry')
    form=re.sub(r'<option[^>]*>[^<]*Cent\$ible[^<]*</option>','',form)
    # An enquiry does not reserve a place or promise an unannounced programme.
    if 'data-form="school"' in form:
        form=re.sub(r'(<select[^>]*id="interest"[^>]*>).*?(</select>)',r'\1<option value="">Select interest</option><option>Crisis Command delegation</option><option>School collaboration</option><option>General school enquiry</option>\2',form,flags=re.S)
    form=form.replace('</form>','<div class="field full"><label class="checkbox"><input type="checkbox" name="contact_consent" required>I consent to the Élan team storing these details and contacting me about this enquiry.</label></div></form>')
    return f'<section class="visitor-enquiry container" id="enquire"><div><p class="section-label">START A CONVERSATION</p><h2>{title}</h2><p>{copy}</p><a class="text-link" href="mailto:the.elan.summit@gmail.com">the.elan.summit@gmail.com ↗</a><p class="visitor-fine">Your enquiry is saved for the organising team. It does not reserve a place or confirm a volunteer role.</p></div><div class="form-card">{form}</div></section>'

def make_page(name,main):
    body=''
    if name=='schools.html':
        body=hero('ÉLAN / STUDENTS & SCHOOLS','Bring your school.<br><em>Broaden their world.</em>','Explore school participation in the second edition, centred on Crisis Command. Start with a conversation about your students and what they hope to learn.','discussion')
        body+=ledger('THE EXPERIENCE','Thinking beyond<br>the classroom.',[('Decisions, with consequences.','Crisis Command asks participants to consider competing priorities, respond to changing information and explain their choices.'),('A team with different strengths.','Research, listening, negotiation and clear communication all have a place alongside public speaking.'),('Planning with your coordinator.','Share your estimated group size and practical needs. Eligibility, pricing, supervision, travel and the programme will be confirmed before registration opens.')])
        body+=enquiry(main,'Tell us about<br>your school.','An enquiry starts the discussion; it does not reserve places. Interested in helping organise the edition? <a href="/school-collaboration.html">Explore school collaboration →</a>')
    elif name=='school-collaboration.html':
        body=hero('ÉLAN / SCHOOL COLLABORATION','Build Élan<br><em>with us.</em>','Bring your students, your ideas and a clear sense of what your school can contribute. Participation and organising collaboration are separate conversations.','teamwork')
        body+=ledger('A SHARED RESPONSIBILITY','A meaningful role.<br>A clear agreement.',[('One point of contact.','Nominate a coordinator to discuss student participation, communication and the scope of your school’s involvement.'),('A contribution that fits.','Tell us where you can help: outreach, faculty coordination, logistics, venue support or student leadership. Responsibilities are agreed with the organising team.'),('Recognition, agreed together.','Website credit, event visibility and other benefits need to match the agreed contribution. These are discussed individually rather than promised in advance.'),('Student welfare comes first.','Supervision, conduct, consent and emergency communication need clear responsibilities before participation is confirmed.')])
        body+='<section class="visitor-callout container"><div><p class="section-label">BEGIN WITH YOUR SCHOOL</p><h2>Let’s find the right<br><em>way to work together.</em></h2></div><a class="btn btn-dark" href="/schools.html#enquire">Start a school enquiry ↗</a></section>'
    elif name=='volunteers.html':
        body=hero('ÉLAN / ORGANISING & VOLUNTEERING','Behind every moment,<br><em>there’s a team.</em>','The experience starts with the people behind it. Tell us your interests, availability and the responsibilities you would like to take on.','opening')
        body+=ledger('BEHIND THE EXPERIENCE','Find your<br>contribution.',[('People & coordination','Registration, participant support, hospitality, guest coordination and audience movement.'),('Programme & production','Crisis Command support, room readiness, stage cues, schedules and logistics.'),('Media & storytelling','Photography, film, design, interviews and event communication.'),('Before you commit','The team will confirm available roles, selection, responsibilities, briefing and dates. An enquiry is not a confirmed appointment.')])
        body+=enquiry(main,'Bring your skills.<br>And your curiosity.','Share relevant experience if you have it, and tell us what you would like to learn. Roles for the second edition are still being planned.')
    elif name=='contact.html':
        body=hero('ÉLAN / CONTACT','Let’s talk<br><em>Élan.</em>','School participation, volunteering, partnerships or a question about the first edition: tell us what brings you here.')
        body+='<section class="contact-ledger container"><div><span>DIRECTOR</span><h2>Akshit Parmar</h2></div><a href="tel:+918160215010"><small>CALL</small>+91 8160215010 ↗</a><a href="mailto:the.elan.summit@gmail.com"><small>EMAIL</small>the.elan.summit@gmail.com ↗</a></section>'
        body+=enquiry(main,'What would you<br>like to discuss?','Include the edition your question relates to. For a school or partnership enquiry, share your organisation and the best way to reach you.')
    return '<main id="main" class="legacy visitor-page">'+body+'</main>' if body else main

def current_faq():
    rows=[('What is planned for the second edition?','Crisis Command will be the only flagship. Cent$ible remains part of the 2026 archive and will not continue in the second edition.'),('Are dates and a venue confirmed?','Dates and venue have not been announced. The September 2026 dates and SGIS Mulshi venue belong to the first edition.'),('Can I register or pay now?','Registration and payments for the second edition are not open. Archived pass prices are not second-edition prices.'),('Who can take part?','Eligibility, team size and the detailed format for the second edition will be announced before registration. The first-edition rules remain available for reference.'),('Can our school get involved?','Yes, you can start a school enquiry now. Share your estimated delegation size and coordinator details on the <a href="/schools.html#enquire">school enquiry page</a>.'),('Can I volunteer or discuss a partnership?','Start with the <a href="/volunteers.html#enquire">volunteer enquiry</a> or <a href="/contact.html#enquire">contact the team</a> about a partnership. Roles and arrangements are agreed separately.'),('Does the enquiry form submit my details?','Yes. It securely saves your enquiry for the organising team. An enquiry does not reserve a place or create a participant account.'),('Where are the first-edition details?','The <a href="/archive.html">2026 archive</a> contains the programme, event formats, photos and policies. Read the <a href="/faqs-2026.html">original-edition FAQs</a> for historical answers.')]
    return '<main id="main" class="legacy visitor-page">'+hero('ÉLAN / YOUR QUESTIONS','A few things,<br><em>made clear.</em>','What is known about the second edition, what is still being planned, and where to find the first-edition record.')+'<section class="container visitor-faq"><div class="search-wrap"><label class="sr-only" for="faqSearch">Search questions</label><input id="faqSearch" type="search" placeholder="Search questions"></div><div class="faq-category">'+''.join(f'<article class="faq-item"><button type="button" class="faq-question">{q}<span class="faq-icon" aria-hidden="true">+</span></button><div class="faq-answer"><p>{a}</p></div></article>' for q,a in rows)+'</div></section></main>'
